1	import React, { useState } from 'react';
2	import type { Feature } from '../../router/routes';
3	import { useJsonResource } from '../../ui/useJsonResource';
4	
5	// Clients feature: add a client (name + email) and list every client. Opening a client
6	// (client-open-<id>) reveals the projects being done for them — the client's own projects listing,
7	// scoped via its /api/clients/<id>/projects endpoint. Owns its own state; talks to its own
8	// /api/clients endpoints. data-testid anchors follow the spec's conventions.
9	type Client = { id: number; name: string; email: string; outstanding: number };
10	// How the clients list is ordered: alphabetically by name, or by how much each client still owes.
11	type SortKey = 'name' | 'outstanding';
12	type Project = { id: number; name: string; clientId: number; clientName: string };
13	type Contact = {
14	  id: number;
15	  clientId: number;
16	  name: string;
17	  email: string;
18	  role: string;
19	  primary: boolean;
20	};
21	type ClientSummary = { projectCount: number; contactCount: number };
22	type StatementInvoice = { id: number; projectId: number; amountDue: number };
23	type StatementProject = { projectId: number; invoices: StatementInvoice[]; subtotal: number };
24	type ClientStatement = {
25	  invoices: StatementInvoice[];
26	  projects: StatementProject[];
27	  outstandingTotal: number;
28	};
29	
30	// Money, the way every invoice figure is shown across the app: a dollar sign and two decimals.
31	function money(amount: number): string {
32	  return `$${Number(amount).toLocaleString('en-US', {
33	    minimumFractionDigits: 2,
34	    maximumFractionDigits: 2,
35	  })}`;
36	}
37	
38	// Every client (and contact) needs a proper email. Same shape the server enforces (see CreateClient
39	// / CreateContact) so the UI and the API agree on what "valid" means.
40	const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
41	function isValidEmail(value: string): boolean {
42	  return EMAIL_RE.test(value.trim());
43	}
44	
45	// A client's statement: all of their invoices in one place, each with what is still owed on it, and
46	// the total still owed across them all. Kept behind an opener so the client detail stays compact.
47	// Opening it also shows a clean, printable summary (statement-print-view) headed with the client's
48	// name and closed with the grand total they owe. Owns its own statement state, scoped to the one
49	// client it is showing; talks to that client's own /api/clients/<id>/statement endpoint.
50	function ClientStatement({ client }: { client: Client }) {
51	  const [statement] = useJsonResource<ClientStatement | null>(
52	    `/api/clients/${client.id}/statement`,
53	    null,
54	  );
55	  const [open, setOpen] = useState(false);
56	
57	  return (
58	    <section data-testid="client-statement">
59	      <button data-testid="client-statement-open" onClick={() => setOpen(true)}>
60	        Statement
61	      </button>
62	      {open && statement && (
63	        <>
64	          <article data-testid="statement-print-view" className="statement-print-view">
65	            <header data-testid="statement-heading">
66	              <h2 data-testid="statement-client-name">{client.name}</h2>
67	              <p data-testid="statement-client-email">{client.email}</p>
68	            </header>
69	            <table data-testid="statement-print-lines">
70	              <tbody>
71	                {statement.invoices.map((inv) => (
72	                  <tr key={inv.id} data-testid={`statement-line-${inv.id}`}>
73	                    <td data-testid="statement-line-label">Invoice #{inv.id}</td>
74	                    <td data-testid="statement-line-amount">{money(inv.amountDue)}</td>
75	                  </tr>
76	                ))}
77	              </tbody>
78	            </table>
79	            <p data-testid="statement-grand-total-row">
80	              <span>Grand total owed</span>
81	              <span data-testid="statement-grand-total">{money(statement.outstandingTotal)}</span>
82	            </p>
83	          </article>
84	          <table data-testid="client-statement-table">
85	            {statement.projects.map((project) => (
86	              <tbody
87	                key={project.projectId}
88	                data-testid={`statement-project-${project.projectId}`}
89	              >
90	                {project.invoices.map((inv) => (
91	                  <tr key={inv.id} data-testid={`statement-invoice-row-${inv.id}`}>
92	                    <td data-testid="statement-invoice-due">{money(inv.amountDue)}</td>
93	                  </tr>
94	                ))}
95	                <tr data-testid="statement-project-subtotal-row">
96	                  <td data-testid="statement-project-subtotal">{money(project.subtotal)}</td>
97	                </tr>
98	              </tbody>
99	            ))}
100	          </table>
101	          <p data-testid="client-outstanding-total">{money(statement.outstandingTotal)}</p>
102	        </>
103	      )}
104	    </section>
105	  );
106	}
107	
108	// Recording one lump sum a client paid, split across several of their open invoices. Opening the
109	// form lists each open invoice with a box for the share of the lump sum applied to it
110	// (payment-alloc-<invoiceId>); submitting records one payment per share, so every invoice's balance
111	// then reflects what was put against it. Owns its own form state, scoped to the one client; reads the
112	// client's statement for the open invoices and talks to that client's own /api/clients/<id>/payments
113	// endpoint.
114	function ClientPayment({ client }: { client: Client }) {
115	  const [statement, reload] = useJsonResource<ClientStatement | null>(
116	    `/api/clients/${client.id}/statement`,
117	    null,
118	  );
119	  const [open, setOpen] = useState(false);
120	  const [amount, setAmount] = useState('');
121	  const [date, setDate] = useState('');
122	  // The share typed against each invoice, held as raw strings keyed by invoice id so the inputs stay
123	  // controlled.
124	  const [allocations, setAllocations] = useState<Record<number, string>>({});
125	
126	  const openInvoices = (statement?.invoices ?? []).filter((inv) => inv.amountDue > 0);
127	
128	  async function submit(e: React.FormEvent) {
129	    e.preventDefault();
130	    if (date.trim() === '') {
131	      return;
132	    }
133	    const shares = openInvoices
134	      .map((inv) => ({ invoiceId: inv.id, amount: Number(allocations[inv.id]) }))
135	      .filter((s) => Number.isFinite(s.amount) && s.amount > 0);
136	    if (shares.length === 0) {
137	      return;
138	    }
139	    await fetch(`/api/clients/${client.id}/payments`, {
140	      method: 'POST',
141	      headers: { 'Content-Type': 'application/json' },
142	      body: JSON.stringify({ amount: Number(amount), date, allocations: shares }),
143	    });
144	    setOpen(false);
145	    setAmount('');
146	    setDate('');
147	    setAllocations({});
148	    await reload();
149	  }
150	
151	  return (
152	    <section data-testid="client-payment">
153	      <button data-testid="client-record-payment" type="button" onClick={() => setOpen(true)}>
154	        Record payment
155	      </button>
156	      {open && (
157	        <form data-testid="payment-form" onSubmit={submit}>
158	          <input
159	            data-testid="payment-form-amount"
160	            placeholder="Amount paid"
161	            value={amount}
162	            onChange={(e) => setAmount(e.target.value)}
163	          />
164	          <input
165	            data-testid="payment-form-date"
166	            type="date"
167	            value={date}
168	            onChange={(e) => setDate(e.target.value)}
169	          />
170	          <table data-testid="payment-alloc-table">
171	            <tbody>
172	              {openInvoices.map((inv) => (
173	                <tr key={inv.id} data-testid={`payment-alloc-row-${inv.id}`}>
174	                  <td data-testid="payment-alloc-due">{money(inv.amountDue)}</td>
175	                  <td>
176	                    <input
177	                      data-testid={`payment-alloc-${inv.id}`}
178	                      placeholder="Applied to this invoice"
179	                      value={allocations[inv.id] ?? ''}
180	                      onChange={(e) =>
181	                        setAllocations((prev) => ({ ...prev, [inv.id]: e.target.value }))
182	                      }
183	                    />
184	                  </td>
185	                </tr>
186	              ))}
187	            </tbody>
188	          </table>
189	          <button data-testid="payment-form-submit" type="submit">
190	            Record payment
191	          </button>
192	        </form>
193	      )}
194	    </section>
195	  );
196	}
197	
198	// A client's at-a-glance counts: how many projects and contacts are kept for them. Owns its own
199	// summary state, scoped to the one client it is showing; talks to that client's own
200	// /api/clients/<id>/summary endpoint.
201	function ClientSummaryBadges({ client }: { client: Client }) {
202	  const [summary] = useJsonResource<ClientSummary>(`/api/clients/${client.id}/summary`, {
203	    projectCount: 0,
204	    contactCount: 0,
205	  });
206	
207	  return (
208	    <section data-testid="client-summary">
209	      <span data-testid="client-projects-count">{summary.projectCount}</span>
210	      <span data-testid="client-contacts-count">{summary.contactCount}</span>
211	    </section>
212	  );
213	}
214	
215	// The add-a-contact form: name, email and role, all required, with the same email check the server
216	// runs. Owns only its own field state and clears itself once the parent has taken the new contact.
217	function ContactForm({
218	  onAdd,
219	}: {
220	  onAdd: (contact: { name: string; email: string; role: string }) => Promise<void>;
221	}) {
222	  const [name, setName] = useState('');
223	  const [email, setEmail] = useState('');
224	  const [role, setRole] = useState('');
225	  const [emailError, setEmailError] = useState('');
226	
227	  async function submit(e: React.FormEvent) {
228	    e.preventDefault();
229	    if (!name.trim() || !email.trim() || !role.trim()) {
230	      return;
231	    }
232	    if (!isValidEmail(email)) {
233	      setEmailError('Enter a valid email address.');
234	      return;
235	    }
236	    setEmailError('');
237	    await onAdd({ name, email, role });
238	    setName('');
239	    setEmail('');
240	    setRole('');
241	  }
242	
243	  return (
244	    <form data-testid="contact-form" onSubmit={submit}>
245	      <input
246	        data-testid="contact-form-name"
247	        placeholder="Name"
248	        value={name}
249	        onChange={(e) => setName(e.target.value)}
250	      />
251	      <input
252	        data-testid="contact-form-email"
253	        placeholder="Email"
254	        value={email}
255	        onChange={(e) => setEmail(e.target.value)}
256	      />
257	      {emailError && (
258	        <p data-testid="contact-form-email-error" role="alert">
259	          {emailError}
260	        </p>
261	      )}
262	      <input
263	        data-testid="contact-form-role"
264	        placeholder="Role"
265	        value={role}
266	        onChange={(e) => setRole(e.target.value)}
267	      />
268	      <button data-testid="contact-form-submit" type="submit">
269	        Add contact
270	      </button>
271	    </form>
272	  );
273	}
274	
275	// The contacts list itself: a row per contact with a control to promote it to the client's primary.
276	function ContactsTable({
277	  contacts,
278	  onMakePrimary,
279	}: {
280	  contacts: Contact[];
281	  onMakePrimary: (id: number) => void;
282	}) {
283	  return (
284	    <table data-testid="client-contacts-table">
285	      <tbody>
286	        {contacts.map((ct) => (
287	          <tr key={ct.id} data-testid={`contact-row-${ct.id}`}>
288	            <td data-testid="contact-name">{ct.name}</td>
289	            <td data-testid="contact-email">{ct.email}</td>
290	            <td data-testid="contact-role">{ct.role}</td>
291	            <td>
292	              <button data-testid={`contact-primary-${ct.id}`} onClick={() => onMakePrimary(ct.id)}>
293	                Make primary
294	              </button>
295	            </td>
296	          </tr>
297	        ))}
298	      </tbody>
299	    </table>
300	  );
301	}
302	
303	// A client's contacts: the people the user keeps for them (name, email, role), with a form to add
304	// another. Owns its own contact state, scoped to the one client it is showing; talks to that
305	// client's own /api/clients/<id>/contacts endpoints. The form and the table are their own pieces so
306	// this stays a thin coordinator: load, add, promote, show who is primary.
307	function ClientContacts({ client }: { client: Client }) {
308	  const [contacts, reload] = useJsonResource<Contact[]>(`/api/clients/${client.id}/contacts`, []);
309	
310	  async function addContact(contact: { name: string; email: string; role: string }) {
311	    await fetch(`/api/clients/${client.id}/contacts`, {
312	      method: 'POST',
313	      headers: { 'Content-Type': 'application/json' },
314	      body: JSON.stringify(contact),
315	    });
316	    await reload();
317	  }
318	
319	  // Pick this contact as the client's one main contact, then refresh so the new primary shows.
320	  async function makePrimary(id: number) {
321	    await fetch(`/api/contacts/${id}/primary`, { method: 'POST' });
322	    await reload();
323	  }
324	
325	  const primary = contacts.find((ct) => ct.primary) ?? null;
326	
327	  return (
328	    <section data-testid="client-contacts">
329	      <p data-testid="client-primary-contact">{primary ? primary.name : ''}</p>
330	      <ContactForm onAdd={addContact} />
331	      <ContactsTable contacts={contacts} onMakePrimary={makePrimary} />
332	    </section>
333	  );
334	}
335	
336	// A client's detail: the projects being done for them. Owns its own project state, scoped to the one
337	// client it is showing. Reuses the project-row-<id>/project-name anchors in a client-scoped table.
338	// Shows only the client's ACTIVE projects by default (scope=active); the show-all toggle asks the
339	// server for everything (scope=all), so the finished and hidden (archived) ones appear too.
340	function ClientProjects({ client }: { client: Client }) {
341	  const [showAll, setShowAll] = useState(false);
342	  const [projects] = useJsonResource<Project[]>(
343	    `/api/clients/${client.id}/projects?scope=${showAll ? 'all' : 'active'}`,
344	    [],
345	  );
346	
347	  return (
348	    <section data-testid="client-projects">
349	      <button data-testid="client-projects-show-all" onClick={() => setShowAll((v) => !v)}>
350	        {showAll ? 'Show only active' : 'Show finished and hidden too'}
351	      </button>
352	      <table data-testid="client-projects-table">
353	        <tbody>
354	          {projects.map((p) => (
355	            <tr key={p.id} data-testid={`project-row-${p.id}`}>
356	              <td data-testid="project-name">{p.name}</td>
357	            </tr>
358	          ))}
359	        </tbody>
360	      </table>
361	    </section>
362	  );
363	}
364	
365	// A name-and-email form for a client, used to add one and reusable for correcting one. `testid` is
366	// the anchor prefix (its fields are `${testid}-name` / `-email` / `-email-error` / `-submit`), so a
367	// second instance (e.g. an edit form) just passes a different prefix. Validates the email format the
368	// way the server does; `onSubmit` returns an error string to show (e.g. a duplicate the server
369	// rejected) or null on success, in which case the form clears back to its initial values.
370	function ClientForm({
371	  testid,
372	  submitLabel,
373	  initial = { name: '', email: '' },
374	  onSubmit,
375	}: {
376	  testid: string;
377	  submitLabel: string;
378	  initial?: { name: string; email: string };
379	  onSubmit: (values: { name: string; email: string }) => Promise<string | null>;
380	}) {
381	  const [name, setName] = useState(initial.name);
382	  const [email, setEmail] = useState(initial.email);
383	  const [emailError, setEmailError] = useState('');
384	
385	  async function submit(e: React.FormEvent) {
386	    e.preventDefault();
387	    if (!isValidEmail(email)) {
388	      setEmailError('Enter a valid email address.');
389	      return;
390	    }
391	    const error = await onSubmit({ name, email });
392	    if (error) {
393	      setEmailError(error);
394	      return;
395	    }
396	    setEmailError('');
397	    setName(initial.name);
398	    setEmail(initial.email);
399	  }
400	
401	  return (
402	    <form data-testid={testid} onSubmit={submit}>
403	      <input
404	        data-testid={`${testid}-name`}
405	        placeholder="Name"
406	        value={name}
407	        onChange={(e) => setName(e.target.value)}
408	      />
409	      <input
410	        data-testid={`${testid}-email`}
411	        placeholder="Email"
412	        value={email}
413	        onChange={(e) => setEmail(e.target.value)}
414	      />
415	      {emailError && (
416	        <p data-testid={`${testid}-email-error`} role="alert">
417	          {emailError}
418	        </p>
419	      )}
420	      <button data-testid={`${testid}-submit`} type="submit">
421	        {submitLabel}
422	      </button>
423	    </form>
424	  );
425	}
426	
427	// The tucked-away clients: those the user archived earlier. Shown behind the "show archived" toggle
428	// so they stay out of the way, each with a control to bring it back (client-restore-<id>) so it
429	// returns to the main list. Reads the archived-only /api/clients/archived listing; restoring is the
430	// mirror of archiving.
431	function ArchivedClients({
432	  clients,
433	  onRestore,
434	}: {
435	  clients: Client[];
436	  onRestore: (id: number) => void;
437	}) {
438	  return (
439	    <table data-testid="clients-archived-table">
440	      <tbody>
441	        {clients.map((c) => (
442	          <tr key={c.id} data-testid={`client-archived-row-${c.id}`}>
443	            <td data-testid="client-name">{c.name}</td>
444	            <td data-testid="client-email">{c.email}</td>
445	            <td>
446	              <button data-testid={`client-restore-${c.id}`} onClick={() => onRestore(c.id)}>
447	                Restore
448	              </button>
449	            </td>
450	          </tr>
451	        ))}
452	      </tbody>
453	    </table>
454	  );
455	}
456	
457	// The client list: a row per client with controls to open its detail or archive it.
458	function ClientsTable({
459	  clients,
460	  onOpen,
461	  onEdit,
462	  onArchive,
463	}: {
464	  clients: Client[];
465	  onOpen: (id: number) => void;
466	  onEdit: (id: number) => void;
467	  onArchive: (id: number) => void;
468	}) {
469	  return (
470	    <table data-testid="clients-table">
471	      <tbody>
472	        {clients.map((c) => (
473	          <tr key={c.id} data-testid={`client-row-${c.id}`}>
474	            <td data-testid="client-name">{c.name}</td>
475	            <td data-testid="client-email">{c.email}</td>
476	            <td data-testid="client-outstanding">{money(c.outstanding)}</td>
477	            <td>
478	              <button data-testid={`client-open-${c.id}`} onClick={() => onOpen(c.id)}>
479	                Open
480	              </button>
481	              <button data-testid={`client-edit-${c.id}`} onClick={() => onEdit(c.id)}>
482	                Edit
483	              </button>
484	              <button data-testid={`client-archive-${c.id}`} onClick={() => onArchive(c.id)}>
485	                Archive
486	              </button>
487	            </td>
488	          </tr>
489	        ))}
490	      </tbody>
491	    </table>
492	  );
493	}
494	
495	function ClientsPage() {
496	  const [clients, reload] = useJsonResource<Client[]>('/api/clients', []);
497	  // The tucked-away clients, loaded alongside the live list so the "show archived" toggle can reveal
498	  // them; kept separate from `clients` so the default list stays exactly the live ones.
499	  const [archived, reloadArchived] = useJsonResource<Client[]>('/api/clients/archived', []);
500	  // Whether the archived clients are on show (so one can be brought back) or tucked away by default.
501	  const [showArchived, setShowArchived] = useState(false);
502	  // Client-side name filter: the list can get long, so a search box narrows it. Case-insensitive
503	  // substring match on the client name; an empty box shows everyone.
504	  const [search, setSearch] = useState('');
505	  // How the list is ordered: by name (default) or by how much each client owes (most first).
506	  const [sort, setSort] = useState<SortKey>('name');
507	  const [openId, setOpenId] = useState<number | null>(null);
508	  // Which client (if any) is being corrected: opening the edit form seeds it with that client's
509	  // current name and email so the user tweaks rather than retypes.
510	  const [editingId, setEditingId] = useState<number | null>(null);
511	
512	  // Two clients cannot share an email; the server rejects a duplicate, so surface it and keep the
513	  // form as-is rather than clearing or reloading (nothing was added).
514	  async function addClient(values: { name: string; email: string }): Promise<string | null> {
515	    const res = await fetch('/api/clients', {
516	      method: 'POST',
517	      headers: { 'Content-Type': 'application/json' },
518	      body: JSON.stringify(values),
519	    });
520	    if (!res.ok) {
521	      return 'A client with this email already exists.';
522	    }
523	    await reload();
524	    return null;
525	  }
526	
527	  // Correct a client's name or email. The server rejects a duplicate email (against another
528	  // client), so surface it and keep the form open; on success reload and close the edit form.
529	  async function editClient(
530	    id: number,
531	    values: { name: string; email: string },
532	  ): Promise<string | null> {
533	    const res = await fetch(`/api/clients/${id}`, {
534	      method: 'PUT',
535	      headers: { 'Content-Type': 'application/json' },
536	      body: JSON.stringify(values),
537	    });
538	    if (!res.ok) {
539	      return 'A client with this email already exists.';
540	    }
541	    await reload();
542	    setEditingId(null);
543	    return null;
544	  }
545	
546	  // Tuck a client away: archived clients are retained server-side but drop off this list and out of
547	  // the search. Reloading after archiving is enough — the /api/clients list excludes them.
548	  async function archive(id: number) {
549	    await fetch(`/api/clients/${id}/archive`, { method: 'POST' });
550	    if (openId === id) {
551	      setOpenId(null);
552	    }
553	    if (editingId === id) {
554	      setEditingId(null);
555	    }
556	    await reload();
557	    await reloadArchived();
558	  }
559	
560	  // Bring a tucked-away client back: clearing its archived flag returns it to the live list and drops
561	  // it from the archived one, so refresh both.
562	  async function restore(id: number) {
563	    await fetch(`/api/clients/${id}/restore`, { method: 'POST' });
564	    await reload();
565	    await reloadArchived();
566	  }
567	
568	  const term = search.trim().toLowerCase();
569	  // Filter by the search box, then order: by name ascending, or by outstanding amount descending
570	  // (the client who owes the most first).
571	  const visible = clients
572	    .filter((c) => c.name.toLowerCase().includes(term))
573	    .sort((a, b) =>
574	      sort === 'outstanding' ? b.outstanding - a.outstanding : a.name.localeCompare(b.name),
575	    );
576	  const open = clients.find((c) => c.id === openId) ?? null;
577	  const editing = clients.find((c) => c.id === editingId) ?? null;
578	
579	  return (
580	    <section data-testid="clients">
581	      <input
582	        data-testid="client-search"
583	        placeholder="Search clients by name"
584	        value={search}
585	        onChange={(e) => setSearch(e.target.value)}
586	      />
587	      <select
588	        data-testid="client-sort"
589	        value={sort}
590	        onChange={(e) => setSort(e.target.value as SortKey)}
591	      >
592	        <option value="name">Name</option>
593	        <option value="outstanding">Outstanding</option>
594	      </select>
595	      <ClientForm testid="client-form" submitLabel="Add client" onSubmit={addClient} />
596	
597	      <button data-testid="clients-show-archived" onClick={() => setShowArchived((v) => !v)}>
598	        {showArchived ? 'Hide archived' : 'Show archived'}
599	      </button>
600	      {showArchived && <ArchivedClients clients={archived} onRestore={restore} />}
601	
602	      {clients.length === 0 ? (
603	        <p data-testid="clients-empty">No clients yet.</p>
604	      ) : (
605	        <ClientsTable
606	          clients={visible}
607	          onOpen={setOpenId}
608	          onEdit={setEditingId}
609	          onArchive={archive}
610	        />
611	      )}
612	
613	      {editing && (
614	        <ClientForm
615	          key={`edit-${editing.id}`}
616	          testid="client-edit-form"
617	          submitLabel="Save changes"
618	          initial={{ name: editing.name, email: editing.email }}
619	          onSubmit={(values) => editClient(editing.id, values)}
620	        />
621	      )}
622	
623	      {open && <ClientSummaryBadges key={`summary-${open.id}`} client={open} />}
624	      {open && <ClientStatement key={`statement-${open.id}`} client={open} />}
625	      {open && <ClientPayment key={`payment-${open.id}`} client={open} />}
626	      {open && <ClientContacts key={`contacts-${open.id}`} client={open} />}
627	      {open && <ClientProjects key={open.id} client={open} />}
628	    </section>
629	  );
630	}
631	
632	export const feature: Feature = { id: 'clients', label: 'Clients', Page: ClientsPage };
