500	// A project's budget: what was set for it, what has been invoiced against it so far, and what is
501	// left over. Invoiced (and so remaining) is derived from the project's invoices, so the owner bumps
502	// `reloadKey` whenever they change and this re-reads the budget picture. Owns its own budget state.
503	function BudgetPanel({ projectId, reloadKey }: { projectId: number; reloadKey: number }) {
504	  const [budget, setBudget] = useState<ProjectBudget | null>(null);
