520	      return;
521	    }
522	    await fetch(`/api/projects/${projectId}/budget`, {
523	      method: 'POST',
524	      headers: { 'Content-Type': 'application/json' },
525	      body: JSON.stringify({ budget: value }),
526	    });
527	    setBudgetInput('');
528	    await load();
529	  }
530	
531	  return (
532	    <section data-testid="project-budget-panel">
533	      <p data-testid="project-budget">
534	        {budget && budget.budget != null ? moneyGrouped(budget.budget) : ''}
535	      </p>
536	      <p data-testid="project-invoiced">{moneyGrouped(budget ? budget.invoiced : 0)}</p>
537	      <p data-testid="project-remaining">
538	        {budget && budget.remaining != null ? moneyGrouped(budget.remaining) : ''}
539	      </p>
540	      <form data-testid="project-budget-form" onSubmit={submit}>
541	        <input
542	          data-testid="project-budget-input"
543	          placeholder="Budget"
544	          value={budgetInput}
545	          onChange={(e) => setBudgetInput(e.target.value)}
546	        />
547	        <button data-testid="project-budget-submit" type="submit">
548	          Set budget
549	        </button>
550	      </form>
551	    </section>
552	  );
553	}
