555	// A project's labels: the ones on it now (each removable) and a picker of the remaining labels to add
556	// another. Owns its own tag state, scoped to the one project.
557	function TagsPanel({ projectId }: { projectId: number }) {
558	  const [tags, reloadTags] = useJsonResource<Tag[]>(`/api/projects/${projectId}/tags`, []);
559	  const [allTags, reloadAllTags] = useJsonResource<Tag[]>('/api/tags', []);
560	  const [tagToAdd, setTagToAdd] = useState('');
561	
562	  async function reload() {
563	    await Promise.all([reloadTags(), reloadAllTags()]);
564	  }
565	
566	  async function addTag(e: React.FormEvent) {
567	    e.preventDefault();
568	    if (!tagToAdd) {
569	      return;
570	    }
571	    await fetch(`/api/projects/${projectId}/tags`, {
572	      method: 'POST',
573	      headers: { 'Content-Type': 'application/json' },
574	      body: JSON.stringify({ tagId: Number(tagToAdd) }),
575	    });
576	    setTagToAdd('');
577	    await reload();
578	  }
579	
580	  async function removeTag(id: number) {
581	    await fetch(`/api/projects/${projectId}/tags/${id}/remove`, { method: 'POST' });
582	    await reload();
583	  }
584	
585	  return (
586	    <>
587	      <div data-testid="project-tags">
588	        {tags.map((tag) => (
589	          <span key={tag.id}>
