591	            <button
592	              data-testid={`project-tag-remove-${tag.id}`}
593	              type="button"
594	              onClick={() => removeTag(tag.id)}
595	            >
596	              Remove
597	            </button>
598	          </span>
599	        ))}
600	      </div>
601	
602	      <form data-testid="project-tag-form" onSubmit={addTag}>
603	        <select
604	          data-testid="project-tag-add"
605	          value={tagToAdd}
606	          onChange={(e) => setTagToAdd(e.target.value)}
607	        >
608	          <option value="">Add a label</option>
609	          {allTags
610	            .filter((t) => !tags.some((mine) => mine.id === t.id))
611	            .map((t) => (
612	              <option key={t.id} value={String(t.id)}>
613	                {t.name}
614	              </option>
615	            ))}
616	        </select>
617	        <button data-testid="project-tag-add-submit" type="submit">
618	          Add label
619	        </button>
620	      </form>
621	    </>
622	  );
