625	// A project's tasks, filterable by whether they are still open or already done, each with a control
626	// to tick it off or reopen it. Owns its own task state, scoped to the one project.
627	function TasksPanel({ projectId }: { projectId: number }) {
628	  const [tasks, reload] = useJsonResource<Task[]>(`/api/tasks?projectId=${projectId}`, []);
629	  const [taskFilter, setTaskFilter] = useState<'ALL' | 'OPEN' | 'DONE'>('ALL');
