671	// The notes jotted against one target (a job or an invoice): a running list, newest first, and a
672	// form to add another. Polymorphic by targetType + targetId so the same panel serves any entity;
673	// the wrapper's data-testid names which surface it is (e.g. project-notes, invoice-notes). Owns its
674	// own note state, scoped to the one target it is showing.
675	function NotesPanel({
676	  targetType,
677	  targetId,
