804	function ProjectsPage() {
805	  const [projects, reloadProjects] = useJsonResource<Project[]>('/api/projects', []);
806	  const [clients] = useJsonResource<Client[]>('/api/clients', []);
807	  const [tags] = useJsonResource<Tag[]>('/api/tags', []);
808	  const [tagLinks] = useJsonResource<ProjectTagLink[]>('/api/project-tags', []);
809	  const [tagFilter, setTagFilter] = useState('');
810	  const [statusFilter, setStatusFilter] = useState('');
811	  const [name, setName] = useState('');
812	  const [code, setCode] = useState('');
813	  const [codeError, setCodeError] = useState('');
814	  const [clientId, setClientId] = useState('');
815	  const [status, setStatus] = useState<ProjectStatus>('ACTIVE');
816	  const [openId, setOpenId] = useState<number | null>(null);
817	  // Archived projects are tucked away (retained, not deleted) and hidden by default; this toggle
818	  // reveals them again.
819	  const [showArchived, setShowArchived] = useState(false);
820	
821	  async function submit(e: React.FormEvent) {
822	    e.preventDefault();
823	    setCodeError('');
824	    if (!name.trim() || !clientId || !code.trim()) {
825	      return;
826	    }
827	    const res = await fetch('/api/projects', {
828	      method: 'POST',
829	      headers: { 'Content-Type': 'application/json' },
830	      body: JSON.stringify({ name, code, clientId: Number(clientId), status }),
831	    });
832	    // A code must be unique across jobs; the server rejects a duplicate, which surfaces here as a
833	    // field error rather than a new row.
834	    if (!res.ok) {
835	      setCodeError('That code is already in use');
836	      return;
837	    }
838	    setName('');
839	    setCode('');
840	    setClientId('');
841	    setStatus('ACTIVE');
842	    await reloadProjects();
843	  }
844	
845	  // Delete and archive are the same shape — POST the action, drop the open detail if it was showing
846	  // this project, then refresh the list — so they share one call site.
847	  async function act(id: number, action: 'delete' | 'archive') {
848	    await fetch(`/api/projects/${id}/${action}`, { method: 'POST' });
849	    if (openId === id) {
850	      setOpenId(null);
851	    }
852	    await reloadProjects();
853	  }
854	
855	  // Narrow the list one step at a time: hide archived unless asked, keep only projects carrying the
856	  // chosen label, then keep only the chosen status. An empty filter leaves that step wide open.
857	  const filterTagId = tagFilter ? Number(tagFilter) : null;
858	  const visible = projects
859	    .filter((p) => showArchived || !p.archived)
860	    .filter(
861	      (p) =>
862	        filterTagId === null ||
863	        tagLinks.some((l) => l.projectId === p.id && l.tagId === filterTagId),
864	    )
865	    .filter((p) => !statusFilter || p.status === statusFilter);
866	  const open = projects.find((p) => p.id === openId) ?? null;
867	
868	  return (
869	    <section data-testid="projects">
870	      <form data-testid="project-form" onSubmit={submit}>
871	        <input
872	          data-testid="project-form-name"
873	          placeholder="Job name"
874	          value={name}
875	          onChange={(e) => setName(e.target.value)}
876	        />
877	        <input
878	          data-testid="project-form-code"
879	          placeholder="Reference code"
880	          value={code}
881	          onChange={(e) => setCode(e.target.value)}
882	        />
883	        <select
884	          data-testid="project-form-client"
885	          value={clientId}
886	          onChange={(e) => setClientId(e.target.value)}
887	        >
888	          <option value="">Select a client</option>
889	          {clients.map((c) => (
890	            <option key={c.id} value={String(c.id)}>
891	              {c.name}
892	            </option>
893	          ))}
894	        </select>
895	        <select
896	          data-testid="project-form-status"
897	          value={status}
898	          onChange={(e) => setStatus(e.target.value as ProjectStatus)}
899	        >
900	          <option value="ACTIVE">Active</option>
901	          <option value="ON_HOLD">On hold</option>
902	          <option value="FINISHED">Finished</option>
903	        </select>
904	        <button data-testid="project-form-submit" type="submit">
905	          Add job
906	        </button>
907	        {codeError && (
908	          <p data-testid="project-form-code-error" role="alert">
909	            {codeError}
910	          </p>
911	        )}
912	      </form>
913	
914	      <button
915	        data-testid="projects-show-archived"
916	        type="button"
917	        onClick={() => setShowArchived((v) => !v)}
918	      >
919	        {showArchived ? 'Hide archived' : 'Show archived'}
920	      </button>
921	
922	      <select
923	        data-testid="project-tag-filter"
924	        value={tagFilter}
925	        onChange={(e) => setTagFilter(e.target.value)}
926	      >
927	        <option value="">All labels</option>
928	        {tags.map((t) => (
929	          <option key={t.id} value={String(t.id)}>
930	            {t.name}
931	          </option>
932	        ))}
933	      </select>
934	
935	      <select
936	        data-testid="project-status-filter"
937	        value={statusFilter}
938	        onChange={(e) => setStatusFilter(e.target.value)}
939	      >
940	        <option value="">All statuses</option>
941	        <option value="ACTIVE">Active</option>
942	        <option value="ON_HOLD">On hold</option>
943	        <option value="FINISHED">Finished</option>
944	      </select>
945	
946	      {projects.length === 0 ? (
947	        <p data-testid="projects-empty">No jobs yet.</p>
948	      ) : (
949	        <ProjectsTable
950	          projects={visible}
951	          onOpen={setOpenId}
952	          onArchive={(id) => act(id, 'archive')}
953	          onDelete={(id) => act(id, 'delete')}
954	        />
955	      )}
956	
957	      {open && <ProjectDetail key={open.id} project={open} />}
958	    </section>
959	  );
960	}
