1	package net.officefloor.hq.app;
2	
3	import java.util.ArrayList;
4	import java.util.List;
5	import java.util.Map;
6	import org.springframework.context.annotation.Profile;
7	import org.springframework.jdbc.core.JdbcTemplate;
8	import org.springframework.web.bind.annotation.PostMapping;
9	import org.springframework.web.bind.annotation.RequestBody;
10	import org.springframework.web.bind.annotation.RequestMapping;
11	import org.springframework.web.bind.annotation.RestController;
12	
13	/**
14	 * Per-spec data setup for the harness (DESIGN.md §9). Profile-guarded so it exists ONLY under the
15	 * harness launch (bin/start sets spring.profiles.active=harness) — never in a real deploy. This is
16	 * APP CODE and EVOLVES with the schema (NOT pinned); a change that breaks a prior spec's seed is a
17	 * seed-path regression. Tests call these to ARRANGE data; they ASSERT only through the UI.
18	 *
19	 * <p>{@link #seed} is a plain sequence of one {@code seed*} method per entity. Teaching a new entity
20	 * to the harness is therefore additive: add its {@code seed*} method, call it from {@link #seed},
21	 * and add its {@code TRUNCATE} to {@link #reset} — no existing entity's code is touched.
22	 */
23	@Profile("harness")
24	@RestController
25	@RequestMapping("/__test__")
26	public class TestSupportController {
27	
28	    private final Audit audit;
29	    private final JdbcTemplate jdbc;
30	
31	    public TestSupportController(Audit audit, JdbcTemplate jdbc) {
32	        this.audit = audit;
33	        this.jdbc = jdbc;
34	    }
35	
36	    /** Truncate all domain tables and clear the audit file so each spec starts clean. */
37	    @PostMapping("/reset")
38	    public void reset() {
39	        audit.clear();
40	        // Referential integrity is dropped for the duration so the tables can be truncated (and
41	        // their identity counters restarted) regardless of FK order (e.g. projects -> clients).
42	        jdbc.execute("SET REFERENTIAL_INTEGRITY FALSE");
43	        for (String table : List.of("dashboard_clock", "notes", "project_tags", "tags", "tasks",
44	                "payments", "line_items", "invoices", "contacts", "projects", "clients")) {
45	            jdbc.execute("TRUNCATE TABLE " + table + " RESTART IDENTITY");
46	        }
47	        jdbc.execute("SET REFERENTIAL_INTEGRITY TRUE");
48	    }
49	
50	    /** Insert the fixture a spec needs; each entity is seeded by its own {@code seed*} method. */
51	    @PostMapping("/seed")
52	    public void seed(@RequestBody Map<String, Object> fixture) {
53	        seedClients(fixture);
54	        seedProjects(fixture);
55	        seedContacts(fixture);
56	        seedInvoices(fixture);
57	        seedPayments(fixture);
58	        seedTasks(fixture);
59	        seedTags(fixture);
60	        seedNotes(fixture);
61	        seedProjectTags(fixture);
62	        seedClock(fixture);
63	    }
64	
65	    private void seedClock(Map<String, Object> fixture) {
66	        // The dashboard's fixed "as of" reference date (top-level asOf), if the fixture supplies one.
67	        Object asOf = fixture.get("asOf");
68	        if (asOf != null) {
69	            jdbc.update("INSERT INTO dashboard_clock (id, as_of) VALUES (1, ?)", asOf.toString());
70	        }
71	    }
72	
73	    private void seedClients(Map<String, Object> fixture) {
74	        for (Map<String, Object> c : rows(fixture, "clients")) {
75	            // archived defaults to FALSE (the table default) unless the fixture pins it, so a
76	            // fixture can seed a tucked-away client for the restore flow.
77	            new Insert("clients")
78	                    .set("id", id(c, "id"))
79	                    .set("name", c.get("name"))
80	                    .set("email", c.get("email"))
81	                    .setIfPresent("archived", c.get("archived"))
82	                    .run();
83	        }
84	    }
85	
86	    private void seedProjects(Map<String, Object> fixture) {
87	        for (Map<String, Object> p : rows(fixture, "projects")) {
88	            // status defaults to ACTIVE so a fixture that omits it gets an active project; archived
89	            // defaults to FALSE (the table default) unless the fixture pins it.
90	            new Insert("projects")
91	                    .set("id", id(p, "id"))
92	                    .set("name", p.get("name"))
93	                    .setIfPresent("code", p.get("code"))
94	                    .set("client_id", id(p, "clientId"))
95	                    .set("status", p.get("status") == null ? "ACTIVE" : p.get("status").toString())
96	                    .setIfPresent("archived", p.get("archived"))
97	                    .setIfPresent("budget", asDouble(p.get("budget")))
98	                    .run();
99	        }
100	    }
101	
102	    private void seedContacts(Map<String, Object> fixture) {
103	        for (Map<String, Object> ct : rows(fixture, "contacts")) {
104	            jdbc.update(
105	                    "INSERT INTO contacts (id, client_id, name, email, role, is_primary)"
106	                            + " VALUES (?, ?, ?, ?, ?, ?)",
107	                    id(ct, "id"), id(ct, "clientId"), ct.get("name"), ct.get("email"),
108	                    ct.get("role"), Boolean.TRUE.equals(ct.get("primary")));
109	        }
110	    }
111	
112	    private void seedInvoices(Map<String, Object> fixture) {
113	        for (Map<String, Object> in : rows(fixture, "invoices")) {
114	            // Insert only the columns the fixture supplies, so the table's own defaults apply when a
115	            // fixture omits them (a plain null would trip the NOT NULL columns). status defaults to
116	            // DRAFT and amount defaults to 0 — an invoice's amount is derived from its line items,
117	            // so fixtures list lineItems rather than a single typed amount.
118	            new Insert("invoices")
119	                    .set("id", id(in, "id"))
120	                    .set("project_id", id(in, "projectId"))
121	                    .set("status", in.get("status") == null ? "DRAFT" : in.get("status").toString())
122	                    .setIfPresent("amount", asDouble(in.get("amount")))
123	                    .setIfPresent("discount_pct", asDouble(in.get("discountPct")))
124	                    .setIfPresent("tax_pct", asDouble(in.get("taxPct")))
125	                    .setIfPresent("issued_date", asText(in.get("issuedDate")))
126	                    .setIfPresent("due_date", asText(in.get("dueDate")))
127	                    .run();
128	            seedLineItems(in);
129	        }
130	    }
131	
132	    private void seedLineItems(Map<String, Object> invoice) {
133	        long invoiceId = id(invoice, "id");
134	        for (Map<String, Object> li : rows(invoice, "lineItems")) {
135	            jdbc.update(
136	                    "INSERT INTO line_items (id, invoice_id, description, qty, unit, unit_price)"
137	                            + " VALUES (?, ?, ?, ?, ?, ?)",
138	                    id(li, "id"), invoiceId, li.get("description"),
139	                    ((Number) li.get("qty")).intValue(),
140	                    li.get("unit") == null ? "" : li.get("unit").toString(),
141	                    ((Number) li.get("unitPrice")).doubleValue());
142	        }
143	    }
144	
145	    private void seedPayments(Map<String, Object> fixture) {
146	        List<Map<String, Object>> payments = rows(fixture, "payments");
147	        for (Map<String, Object> p : payments) {
148	            jdbc.update(
149	                    "INSERT INTO payments (id, invoice_id, amount, paid_date) VALUES (?, ?, ?, ?)",
150	                    id(p, "id"), id(p, "invoiceId"), asDouble(p.get("amount")),
151	                    asText(p.get("date")));
152	        }
153	        if (!payments.isEmpty()) {
154	            // Seeding explicit ids does not advance H2's identity counter, so bump it past the
155	            // seeded rows or the app's next generated payment id would collide with a fixture id.
156	            Long next = jdbc.queryForObject("SELECT MAX(id) + 1 FROM payments", Long.class);
157	            jdbc.execute("ALTER TABLE payments ALTER COLUMN id RESTART WITH " + next);
158	        }
159	    }
160	
161	    private void seedTasks(Map<String, Object> fixture) {
162	        for (Map<String, Object> t : rows(fixture, "tasks")) {
163	            jdbc.update("INSERT INTO tasks (id, project_id, title, done) VALUES (?, ?, ?, ?)",
164	                    id(t, "id"), id(t, "projectId"), t.get("title"),
165	                    Boolean.TRUE.equals(t.get("done")));
166	        }
167	    }
168	
169	    private void seedTags(Map<String, Object> fixture) {
170	        for (Map<String, Object> tg : rows(fixture, "tags")) {
171	            jdbc.update("INSERT INTO tags (id, name) VALUES (?, ?)", id(tg, "id"), tg.get("name"));
172	        }
173	    }
174	
175	    private void seedNotes(Map<String, Object> fixture) {
176	        List<Map<String, Object>> notes = rows(fixture, "notes");
177	        for (Map<String, Object> n : notes) {
178	            jdbc.update(
179	                    "INSERT INTO notes (id, target_type, target_id, text, created_at)"
180	                            + " VALUES (?, ?, ?, ?, ?)",
181	                    id(n, "id"), n.get("targetType"), id(n, "targetId"), n.get("text"),
182	                    n.get("at").toString());
183	        }
184	        if (!notes.isEmpty()) {
185	            // Seeding explicit ids does not advance H2's identity counter, so bump it past the
186	            // seeded rows or the app's next generated note id would collide with a fixture id.
187	            Long next = jdbc.queryForObject("SELECT MAX(id) + 1 FROM notes", Long.class);
188	            jdbc.execute("ALTER TABLE notes ALTER COLUMN id RESTART WITH " + next);
189	        }
190	    }
191	
192	    private void seedProjectTags(Map<String, Object> fixture) {
193	        for (Map<String, Object> pt : rows(fixture, "projectTags")) {
194	            jdbc.update("INSERT INTO project_tags (project_id, tag_id) VALUES (?, ?)",
195	                    id(pt, "projectId"), id(pt, "tagId"));
196	        }
197	    }
198	
199	    /** The list of fixture rows under {@code key}, or an empty list when the fixture omits it. */
200	    @SuppressWarnings("unchecked")
201	    private static List<Map<String, Object>> rows(Map<String, Object> fixture, String key) {
202	        return (List<Map<String, Object>>) fixture.getOrDefault(key, List.of());
203	    }
204	
205	    /** A fixture id column: JSON numbers arrive as {@link Number}, the tables use {@code BIGINT}. */
206	    private static long id(Map<String, Object> row, String key) {
207	        return ((Number) row.get(key)).longValue();
208	    }
209	
210	    private static Double asDouble(Object value) {
211	        return value == null ? null : ((Number) value).doubleValue();
212	    }
213	
214	    private static String asText(Object value) {
215	        return value == null ? null : value.toString();
216	    }
