package net.officefloor.hq.app.client;

import java.util.regex.Pattern;
import net.officefloor.hq.app.Audit;
import net.officefloor.server.http.HttpException;
import net.officefloor.server.http.HttpStatus;
import net.officefloor.web.HttpPathParameter;
import net.officefloor.web.ObjectResponse;
import org.springframework.web.bind.annotation.RequestBody;

/**
 * PUT /api/clients/{id} — correct a client's name and/or email. Same email shape the UI and
 * {@link CreateClient} enforce, and the same rule that two clients cannot share an email (the
 * client's own current email is of course allowed). Records the change to the audit file and
 * returns the updated client.
 */
public class UpdateClient {

    /** A client needs a proper email; same shape the UI enforces (see feature.tsx). */
    private static final Pattern EMAIL = Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$");

    public void service(@HttpPathParameter("id") String id, @RequestBody NewClient body,
            ClientRepository repository, Audit audit, ObjectResponse<Client> response) {
        Long clientId = Long.valueOf(id);
        Client client = repository.findById(clientId)
                .orElseThrow(() -> new HttpException(HttpStatus.NOT_FOUND, "No such client"));
        String name = body.getName() == null ? "" : body.getName().trim();
        String email = body.getEmail() == null ? "" : body.getEmail().trim();
        if (name.isEmpty()) {
            throw new HttpException(HttpStatus.BAD_REQUEST, "A client requires a name");
        }
        if (!EMAIL.matcher(email).matches()) {
            throw new HttpException(HttpStatus.BAD_REQUEST,
                    "A client requires a valid email address");
        }
        // Two clients cannot share an email; a duplicate against ANOTHER client is rejected, but the
        // client keeping its own current email is fine.
        if (repository.existsByEmailAndIdNot(email, clientId)) {
            throw new HttpException(HttpStatus.CONFLICT,
                    "A client with this email already exists");
        }
        client.setName(name);
        client.setEmail(email);
        Client saved = repository.save(client);
        audit.record("CLIENT_UPDATED id=" + saved.getId());
        response.send(saved);
    }
}

package net.officefloor.hq.app.client;

import java.util.List;
import net.officefloor.web.ObjectResponse;
import org.springframework.jdbc.core.JdbcTemplate;

/**
 * GET /api/clients — every client still in play (archived clients are tucked away), each with how
 * much they still owe so the list can be sorted by name or by outstanding amount.
 *
 * <p>A client's outstanding is the sum, across every invoice raised for them (via their projects),
 * of what is still due on that invoice — line items (qty * unit price) less its discount, plus sales
 * tax, less everything paid against it. This mirrors the per-client statement total.
 */
public class ListClients {

    public void service(JdbcTemplate jdbc, ObjectResponse<List<ClientListView>> response) {
        List<ClientListView> clients = jdbc.query(
                "SELECT c.id AS id, c.name AS name, c.email AS email, "
                        + "COALESCE((SELECT SUM("
                        + "COALESCE((SELECT SUM(li.qty * li.unit_price) FROM line_items li "
                        + "WHERE li.invoice_id = i.id), 0) * (100 - i.discount_pct) / 100 "
                        + "* (100 + i.tax_pct) / 100 "
                        + "- COALESCE((SELECT SUM(p.amount) FROM payments p "
                        + "WHERE p.invoice_id = i.id), 0)) "
                        + "FROM invoices i JOIN projects pr ON pr.id = i.project_id "
                        + "WHERE pr.client_id = c.id), 0) AS outstanding "
                        + "FROM clients c WHERE c.archived = FALSE ORDER BY c.id",
                (rs, i) -> new ClientListView(rs.getLong("id"), rs.getString("name"),
                        rs.getString("email"), rs.getBigDecimal("outstanding")));
        response.send(clients);
    }
}

