1	package net.officefloor.hq.app.invoice;
2	
3	import java.util.List;
4	import net.officefloor.web.HttpQueryParameter;
5	import net.officefloor.web.ObjectResponse;
6	import org.springframework.jdbc.core.JdbcTemplate;
7	
8	/** GET /api/invoices?projectId=<id> — every invoice for one project, oldest first. */
9	public class ListInvoices {
10	
11	    public void service(@HttpQueryParameter("projectId") String projectId, JdbcTemplate jdbc,
12	            ObjectResponse<List<InvoiceView>> response) {
13	        // The invoice amount is the sum of its line items (qty * unit price) less its discount, then
14	        // with sales tax added on top of that discounted base (tax is worked out after the
15	        // discount); an invoice with no lines totals zero. The amount due is that amount less
16	        // everything paid against it (the sum of its payments), so a fully paid invoice shows zero
17	        // still to pay.
18	        List<InvoiceView> invoices = jdbc.query(
19	                "SELECT id, project_id, status, issued_date, due_date, discount_pct, tax_pct, "
20	                        + "COALESCE((SELECT SUM(li.qty * li.unit_price) FROM line_items li "
21	                        + "WHERE li.invoice_id = invoices.id), 0) * (100 - discount_pct) / 100 "
22	                        + "* (100 + tax_pct) / 100 AS amount, "
23	                        + "COALESCE((SELECT SUM(li.qty * li.unit_price) FROM line_items li "
24	                        + "WHERE li.invoice_id = invoices.id), 0) * (100 - discount_pct) / 100 "
25	                        + "* (100 + tax_pct) / 100 "
26	                        + "- COALESCE((SELECT SUM(p.amount) FROM payments p "
27	                        + "WHERE p.invoice_id = invoices.id), 0) AS amount_due FROM invoices"
28	                        + " WHERE project_id = ? ORDER BY id",
29	                (rs, i) -> {
30	                    java.math.BigDecimal amount = rs.getBigDecimal("amount");
31	                    java.math.BigDecimal amountDue = rs.getBigDecimal("amount_due");
32	                    // Paid = the whole amount less what is still due; the status is worked out from
33	                    // that rather than read from the stored flag.
34	                    String status = InvoiceStatus.derive(rs.getString("status"), amount,
35	                            amount.subtract(amountDue));
36	                    InvoiceView view = new InvoiceView(rs.getLong("id"), rs.getLong("project_id"),
37	                            amount, amountDue, status, rs.getString("issued_date"),
38	                            rs.getString("due_date"));
39	                    view.setDiscountPct(rs.getBigDecimal("discount_pct"));
40	                    view.setTaxPct(rs.getBigDecimal("tax_pct"));
41	                    return view;
42	                },
43	                Long.valueOf(projectId));
44	        response.send(invoices);
45	    }
46	}
